 public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");Directory.CreateDirectory(Folder);Directory.CreateDirectory("Docs/MountainCut");EditorSceneManager.OpenScene("Assets/Scenes/MountainLoopReverse.unity");Physics.SyncTransforms();var race=Object.FindAnyObjectByType<RaceDirector>();var road=race.road;road.Initialize();var branch=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Summit Traverse");branch.Initialize();var driving=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<MeshCollider>();var support=GameObject.Find("Ground_MountainPolish supported shoulders").GetComponent<MeshFilter>();var mat=support.GetComponent<Renderer>().sharedMaterial;var notes=new List<string>();
 // Dependency inventory before modifying supporting meshes.
