 var banks=new List<Face>();
 void Skirts(Func<float,Vector3> at,float start,float end){foreach(int side in new[]{-1,1}){Vector3 previous=default,previousOuter=default,previousToe=default;bool valid=false;for(float s=start;s<=end+.1f;s+=1){var p=at(s);var f=(at(s+.25f)-at(s-.25f)).normalized;var right=Vector3.Cross(Vector3.up,f).normalized;Vector3 edge=default;bool found=false;for(float w=3;w<=15;w+=.25f){var q=p+right*(w*side);if(driving.Raycast(new Ray(q+Vector3.up*1.5f,Vector3.down),out var h,3)){edge=h.point;found=true;}else if(found)break;}if(!found){valid=false;continue;}edge.y-=.06f;var outer=edge+right*(side*1.3f);outer.y-=.25f;var toe=outer+right*(side*Mathf.Clamp((outer.y-Ground(outer))*1.3f,4,22));toe.y=Mathf.Min(outer.y-.15f,Ground(toe));if(valid){if(side==1){Quad(banks,previous,edge,outer,previousOuter);Quad(banks,previousOuter,outer,toe,previousToe);}else{Quad(banks,edge,previous,previousOuter,outer);Quad(banks,outer,previousOuter,previousToe,toe);}}previous=edge;previousOuter=outer;previousToe=toe;valid=true;}}}
 Skirts(s=>road.At(s,out _),390,520);Skirts(s=>branch.At(s,out _),0,branch.Length-18);
 // Reserve each route layer's full clearance, not a single crossing hole.
 var volumes=new List<Plane[]>();for(float s=800;s<962;s+=2)volumes.Add(Box(road.At(s,out _),road.At(s+2,out _),9,-.12f,7.3f));
 for(float s=390;s<520;s+=3)volumes.Add(Box(road.At(s,out _),road.At(s+3,out _),6.9f,-.12f,7));
 for(float s=0;s<branch.Length;s+=3)volumes.Add(Box(branch.At(s,out _),branch.At(Mathf.Min(s+3,branch.Length),out _),6.2f,-.12f,7));
 List<Face> Carve(List<Face> input){foreach(var volume in volumes){var next=new List<Face>();foreach(var f in input)next.AddRange(Subtract(f,volume));input=next;}return input;}
 banks=Carve(banks);Make("MountainCut natural embankments",banks,mat);notes.Add("Replacement embankment faces="+banks.Count);
 // Remove remaining original support intrusions in the lower-road envelope only.
 foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&m.name.StartsWith("Ground_")&&m.gameObject!=driving.gameObject&&m!=support&&!m.name.Contains("MountainCut")).ToArray()){
 var fs=Read(mf);bool changed=false;for(float s=830;s<950;s+=2){var vol=Box(road.At(s,out _),road.At(s+2,out _),9,-.1f,7.3f);var next=new List<Face>();foreach(var f in fs){if(!f.v.Any(v=>v.p.x>970&&v.p.x<1010&&v.p.z>100&&v.p.z<215)){next.Add(f);continue;}var pieces=Subtract(f,vol).ToArray();if(pieces.Length!=1||pieces[0]!=f)changed=true;next.AddRange(pieces);}fs=next;}if(changed){Assign(mf,"cut-"+mf.name.Replace('/','-'),fs);notes.Add("Carved lower clearance in "+mf.name);}}
 // Rock vault under the upper road: 18m opening, 7.8m minimum headroom.
 // Portals and side rock slope outward into the mountain, never a floor or a route change.
 var shell=new List<Face>();for(int z=112;z<144;z+=2){float floor(float zz)=>road.At(road.Project(new Vector3(990,152,zz),out _),out _).y;Vector3[] Section(float zz){float y=floor(zz);return new[]{new Vector3(977,y-2,zz),new Vector3(980,y+5.2f,zz),new Vector3(982,y+7.8f,zz),new Vector3(990,y+8.4f,zz),new Vector3(998,y+7.8f,zz),new Vector3(1000,y+5.2f,zz),new Vector3(1003,y-2,zz)};}var a=Section(z);var b=Section(z+2);for(int i=0;i<a.Length-1;i++)Quad(shell,a[i],b[i],b[i+1],a[i+1],true,true);}
