 foreach(float z in new[]{112f,144f}){float y=road.At(road.Project(new Vector3(990,152,z),out _),out _).y;var inner=new[]{new Vector3(977,y-2,z),new Vector3(980,y+5.2f,z),new Vector3(982,y+7.8f,z),new Vector3(990,y+8.4f,z),new Vector3(998,y+7.8f,z),new Vector3(1000,y+5.2f,z),new Vector3(1003,y-2,z)};for(int i=0;i<inner.Length-1;i++){var a=inner[i];var b=inner[i+1];var aa=a;var bb=b;aa.x=990+(aa.x-990)*1.4f;bb.x=990+(bb.x-990)*1.4f;aa.y=Mathf.Min(163.6f,a.y+3.2f);bb.y=Mathf.Min(163.6f,b.y+3.2f);Quad(shell,a,b,bb,aa,true,true);}}
 shell=Carve(shell);Make("MountainCut rock vault",shell,mat);Physics.SyncTransforms();
 // Natural visible colliding boulders protect selected exposed upper shoulders.
 var stones=new List<string>();foreach(float s in new[]{54f,72f,92f,118f,142f,170f,198f,222f}){var p=branch.At(s,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;var q=p+side*8.1f;if(Physics.Raycast(new Ray(q+Vector3.up*3,Vector3.down),out var hit,20,1,QueryTriggerInteraction.Ignore)&&hit.collider.name.StartsWith("Ground_")){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="Summit natural edge boulder";g.transform.position=hit.point+Vector3.up*.55f;g.transform.localScale=new Vector3(2.7f,1.9f,2.5f);g.GetComponent<Renderer>().sharedMaterial=mat;var mesh=Object.Instantiate(g.GetComponent<MeshFilter>().sharedMesh);mesh.colors=Enumerable.Repeat(Rock,mesh.vertexCount).ToArray();AssetDatabase.CreateAsset(mesh,Folder+"/boulder-"+s+".asset");g.GetComponent<MeshFilter>().sharedMesh=mesh;stones.Add(g.transform.position.ToString());}}
 // Gate visuals only. Preserve trigger transform, dimensions, order and progression.
 var gate=race.gates[1];foreach(var r in gate.GetComponentsInChildren<Renderer>()){if(r.bounds.size.y<1)r.transform.position+=Vector3.up*3.5f;else{var sc=r.transform.localScale;sc.y*=1.875f;r.transform.localScale=sc;r.transform.position+=Vector3.up*1.75f;}}notes.Add("Raised CP1 visual crossbar 3.5m; checkpoint data unchanged");
 Physics.SyncTransforms();foreach(var sign in signs){var rs=sign.GetComponentsInChildren<Renderer>();var posts=rs.Where(r=>r.name.IndexOf("post",StringComparison.OrdinalIgnoreCase)>=0).ToArray();if(posts.Length==0)continue;float foot=posts.Min(r=>r.bounds.min.y);var p=sign.transform.position;var hits=Physics.RaycastAll(new(p.x,foot+25,p.z),Vector3.down,90,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).ToArray();if(hits.Length==0)continue;float ground=hits.Max(h=>h.point.y);sign.transform.position+=Vector3.up*(ground-foot+.03f);notes.Add("Grounded sign "+sign.name+" delta="+(ground-foot));}
 foreach(var t in props){var rs=t.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var p=rs[0].bounds.center;float foot=rs.Min(r=>r.bounds.min.y);var hits=Physics.RaycastAll(new(p.x,foot+20,p.z),Vector3.down,70,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).ToArray();if(hits.Length>0)t.position+=Vector3.up*(hits.Max(h=>h.point.y)-foot);}
