 EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllLines("Docs/MountainCut/authoring.txt",notes);return string.Join("\n",notes);
