 public static string RestoreGrade(){
 var race=Object.FindAnyObjectByType<RaceDirector>();var road=race.road;var branch=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Summit Traverse");var oldMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Track/LocalRecovery/Surgical-second-arrow-Ground_CR133 mountain driving surface.asset");var temp=new GameObject("Temporary original grade",typeof(MeshCollider));var mc=temp.GetComponent<MeshCollider>();mc.sharedMesh=oldMesh;Physics.SyncTransforms();
 float Height(Vector3 p){return mc.Raycast(new Ray(new(p.x,185,p.z),Vector3.down),out var h,45)?h.point.y:p.y;}
 int moved=0;foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&(m.name.Contains("driving surface")||m.name.Contains("arrow")||m.name.Contains("Main teal")))){var vs=mf.sharedMesh.vertices;bool changed=false;for(int i=0;i<vs.Length;i++){var p=mf.transform.TransformPoint(vs[i]);if(p.x<981||p.x>999||p.z<72||p.z>110||p.y<145||p.y>180)continue;float y=Height(p);bool marking=mf.name.Contains("arrow")||mf.name.Contains("Main teal");float target=y+(marking?.075f:0);if(Math.Abs(p.y-target)<.001f)continue;p.y=target;vs[i]=mf.transform.InverseTransformPoint(p);changed=true;moved++;}if(!changed)continue;var mesh=Object.Instantiate(mf.sharedMesh);mesh.vertices=vs;mesh.RecalculateNormals();mesh.RecalculateBounds();var path=Folder+"/restored-"+mf.name.Replace('/','-')+".asset";AssetDatabase.CreateAsset(mesh,path);mf.sharedMesh=mesh;if(mf.TryGetComponent<MeshCollider>(out var c))c.sharedMesh=mesh;}
