 foreach(float z in new[]{112f,144f}){var a=Ring(z);for(int i=0;i<a.Length-1;i++){var aa=a[i];var bb=a[i+1];aa.y=Mathf.Max(aa.y,163.3f);bb.y=Mathf.Max(bb.y,163.3f);Quad(fs,a[i],a[i+1],bb,aa,true,true);}}
