 var bank=GameObject.Find("Ground_MountainCut natural embankments").GetComponent<MeshFilter>();var fs=Read(bank);for(float s=820;s<970;s+=3){var vol=Box(road.At(s,out _),road.At(s+3,out _),8.5f,-.12f,7.1f);fs=fs.SelectMany(f=>Subtract(f,vol)).ToList();}Assign(bank,"MountainCut natural embankments",fs);
 // Close portal perimeter with continuous rock slopes tied into adjacent earth.
 var vault=GameObject.Find("Ground_MountainCut rock vault").GetComponent<MeshFilter>();fs=Read(vault);foreach(float z in new[]{112f,144f}){float floor=z>120?152:Y(z);var inner=new[]{new Vector3(977,floor-2,z),new Vector3(980,floor+5.2f,z),new Vector3(982,floor+7.8f,z),new Vector3(990,floor+8.4f,z),new Vector3(998,floor+7.8f,z),new Vector3(1000,floor+5.2f,z),new Vector3(1003,floor-2,z)};for(int i=0;i<inner.Length-1;i++){var a=inner[i];var b=inner[i+1];var aa=a;var bb=b;aa.x=990+(a.x-990)*1.8f;bb.x=990+(b.x-990)*1.8f;aa.y=i<2||i>3?floor+5:163.7f;bb.y=i<1||i>3?floor+5:163.7f;aa.z+=z==144?6:-5;bb.z=aa.z;Quad(fs,a,b,bb,aa,true,true);}}Assign(vault,"MountainCut rock vault",fs);
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/MountainCut/final-grade.txt",$"Restored {changed} lower vertices against actual historical road samples. Exact X/Z maintained; branch stations reseated to unchanged world-space anchors.");return "Restored original lower layer without sampling upper road; branch anchors preserved";
 }
 public static string CorrectEdges(){
 var race=Object.FindAnyObjectByType<RaceDirector>();var road=race.road;var mf=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<MeshFilter>();var lower=road.points.Where(p=>Math.Abs(p.x-990)<.01f&&p.z>=60&&p.z<=120).OrderBy(p=>p.z).ToArray();float Y(float z){for(int i=1;i<lower.Length;i++)if(z<=lower[i].z)return Mathf.Lerp(lower[i-1].y,lower[i].y,Mathf.InverseLerp(lower[i-1].z,lower[i].z,z));return lower.Last().y;}
 var mesh=Object.Instantiate(mf.sharedMesh);var vs=mesh.vertices;int count=0;for(int i=0;i<vs.Length;i++){var p=vs[i];if((Math.Abs(p.x-976)<.001f||Math.Abs(p.x-1004)<.001f)&&p.z>=72&&p.z<=98&&p.y>150&&p.y<175){vs[i]=new(p.x,Y(p.z)+.04f,p.z);count++;}}mesh.vertices=vs;mesh.RecalculateNormals();mesh.RecalculateBounds();var old=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/restored-driving.asset");EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mf.sharedMesh=old;mf.GetComponent<MeshCollider>().sharedMesh=null;mf.GetComponent<MeshCollider>().sharedMesh=old;EditorUtility.SetDirty(old);
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();File.AppendAllText("Docs/MountainCut/final-grade.txt",$"\nActual 28m-wide lower pavement edges restored: {count} vertices.");return "Restored both actual lower-pavement edges: "+count;
 }
 public static string Dependencies(){var race=Object.FindAnyObjectByType<RaceDirector>();var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Summit Traverse");var mf=GameObject.Find("Ground_Mountain_1_2").GetComponent<MeshFilter>();var fs=Read(mf);for(float s=322;s<344;s+=2){var vol=Box(b.At(s,out _),b.At(s+2,out _),6.4f,-.1f,7);fs=fs.SelectMany(f=>Subtract(f,vol)).ToList();}Assign(mf,"upper-shoulder-seam",fs);
 // Remove thin old support curtains immediately around the new vault, retaining terrain beyond it.
 var cut=new[]{new Plane(Vector3.right,new Vector3(973,0,0)),new Plane(Vector3.left,new Vector3(1007,0,0)),new Plane(Vector3.forward,new Vector3(0,0,110)),new Plane(Vector3.back,new Vector3(0,0,149)),new Plane(Vector3.up,new Vector3(0,151.9f,0)),new Plane(Vector3.down,new Vector3(0,164.1f,0))};
 foreach(var m in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&(m.name.Contains("earth banks")||m.name.Contains("natural embankments")))){var tris=Read(m);var next=tris.SelectMany(f=>Subtract(f,cut)).ToList();Assign(m,"portal-"+m.name,next);}
 // Continuous earth cap above the rock opening seats under the actual upper surface.
 var cap=new List<Face>();var driving=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<Collider>();Vector3 Top(float x,float z){float y=163.35f-.075f*(x-990)+.02f*(z-125);var p=new Vector3(x,y,z);if(driving.Raycast(new Ray(p+Vector3.up*2,Vector3.down),out var h,4)&&h.point.y>158)p.y=Mathf.Min(p.y,h.point.y-.08f);return p;}
 for(float x=973;x<1007;x+=1)for(float z=110;z<149;z+=1)Quad(cap,Top(x,z),Top(x,z+1),Top(x+1,z+1),Top(x+1,z));
 var vault=GameObject.Find("Ground_MountainCut rock vault").GetComponent<MeshFilter>();var material=vault.GetComponent<Renderer>().sharedMaterial;Make("MountainCut mountain cap",cap,material);
 Physics.SyncTransforms();var trees=Object.FindObjectsByType<Collider>().Where(c=>c.name.IndexOf("trunk",StringComparison.OrdinalIgnoreCase)>=0&&Local(c.bounds.center)).Where(c=>{var p=c.bounds.center;var hits=Physics.RaycastAll(new(p.x,c.bounds.min.y+20,p.z),Vector3.down,80,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).ToArray();return hits.Length>0&&Math.Abs(c.bounds.min.y-hits.Max(h=>h.point.y))>.08f;}).ToArray();if(trees.Length>0)typeof(Racer.Editor.BackyardReverseAuthoring).GetMethod("Trees",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{(Func<Collider,bool>)(c=>false),(Func<Collider,bool>)(c=>trees.Contains(c))});
 EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/MountainCut/dependency-final.txt","Upper shoulder clipped to driving level; portal curtains replaced by continuous cap; complete trees reseated="+trees.Length);return "Local seams and dependencies refitted; trees="+trees.Length;
 }
 public static string RockBanks(){var race=Object.FindAnyObjectByType<RaceDirector>();var road=race.road;var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Summit Traverse");var fs=new List<Face>();foreach(float x in new[]{969f,1011f}){Vector3 P(int ring,int i){float a=i*Mathf.PI*2/16;float radius=new[]{.8f,1f,.96f,.75f,.30f}[ring];float y=new[]{137f,145f,153f,160f,163f}[ring];return new Vector3(x+Mathf.Cos(a)*15*radius,y+(ring==0?0:.25f*Mathf.Sin(a*3)),129+Mathf.Sin(a)*28*radius);}for(int r=0;r<4;r++)for(int i=0;i<16;i++)Quad(fs,P(r,i),P(r,i+1),P(r+1,i+1),P(r+1,i),true,true);for(int i=0;i<16;i++)fs.Add(new Face(R(P(4,i)),R(P(4,i+1)),R(new Vector3(x,163.1f,129))));}
 var volumes=new List<Plane[]>();for(float s=810;s<970;s+=3)volumes.Add(Box(road.At(s,out _),road.At(s+3,out _),9,-.15f,7.3f));for(float s=380;s<525;s+=3)volumes.Add(Box(road.At(s,out _),road.At(s+3,out _),8,-.15f,7));for(float s=0;s<75;s+=3)volumes.Add(Box(b.At(s,out _),b.At(s+3,out _),7,-.15f,7));foreach(var vol in volumes)fs=fs.SelectMany(f=>Subtract(f,vol)).ToList();var mat=GameObject.Find("Ground_MountainCut rock vault").GetComponent<Renderer>().sharedMaterial;Make("MountainCut portal outcrops",fs,mat);Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();return "Natural portal outcrops support upper shoulders around the 18m lower opening";}
 public static string ClearBuriedContacts(){var race=Object.FindAnyObjectByType<RaceDirector>();var road=race.road;var vols=new List<Plane[]>();for(float s=815;s<980;s+=3)vols.Add(Box(road.At(s,out _),road.At(s+3,out _),9,-4,7.3f));int count=0;foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&m.name.StartsWith("Ground_MountainCut"))){var fs=Read(mf);foreach(var vol in vols)fs=fs.SelectMany(f=>Subtract(f,vol)).ToList();Assign(mf,"clear-"+mf.name,fs);count++;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/MountainCut/buried-contact-fix.txt","Removed secondary support faces through 4m below the lower pavement, preserving the driving surface. These faces were missed by above-floor probes and contacted the vehicle suspension/body. Meshes="+count);return "Cleared buried secondary support collision in "+count+" meshes";}
 public static string TrimUpperOnly(){var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Summit Traverse");var mf=GameObject.Find("Ground_Mountain_1_2").GetComponent<MeshFilter>();var fs=Read(mf);for(float s=322;s<344;s+=2){var vol=Box(b.At(s,out _),b.At(s+2,out _),6.4f,-.1f,7);fs=fs.SelectMany(f=>Subtract(f,vol)).ToList();}Assign(mf,"upper-shoulder-seam",fs);EditorSceneManager.MarkSceneDirty(b.gameObject.scene);EditorSceneManager.SaveScene(b.gameObject.scene);AssetDatabase.SaveAssets();return "Only the upper road shoulder intersection is trimmed; native hillside retained";}
